slate 1 "Pull request"

root: column
  none: empty title="No pull request yet" body="This branch has no pull request." when={pr.number == null}
  head: facts when={pr.number != null}
    - fact label="State" value={pr.word}
    - fact label="Review" value={pr.review}
    - fact label="Mergeable" value={pr.mergeable} tone={pr.mergeable == 'mergeable' ? 'good' : (pr.mergeable == 'conflicting' ? 'warning' : 'muted')}
  checks: table items={pr.checks} key={item.name} empty="No checks yet" when={pr.number != null}
    - col title="Check" value={item.name}
    - col title="State" value={item.state} tone={item.state == 'fail' ? 'bad' : (item.state == 'pass' ? 'good' : (item.state == 'pending' ? 'warning' : 'muted'))}
    - col title="Took" value={item.completedAt ? duration(num(item.completedAt) - num(item.startedAt)) : 'running'} mono align=end
    - action label="Hand to agent" when={item.state == 'fail'}
      @press send text="A pull request check failed. Read its log and fix it." with=[item.name, item.link]
  fix: button label="Fix all failing checks" primary when={contains(pluck(pr.checks, 'state'), 'fail')}
    @press send text="Fix all the failing pull request checks shown on the slate." with=[pr.checks]
